import {loadEnvFile,sheets,spreadsheetId,id,now,hashPassword} from "./common.mjs";
await loadEnvFile();
const sleep=(ms)=>new Promise((r)=>setTimeout(r,ms));
let lastCall=0;
async function paced(fn){
  const gap=Math.max(0,400-(Date.now()-lastCall));
  if(gap) await sleep(gap);
  lastCall=Date.now();
  for(let attempt=0;attempt<8;attempt++){
    try{return await fn();}
    catch(e){
      const code=e?.code||e?.status||e?.response?.status;
      if(Number(code)===429&&attempt<7){const wait=Math.min(60000,8000*(attempt+1));console.warn(`Sheets quota hit; waiting ${Math.round(wait/1000)}s…`);await sleep(wait);continue;}
      throw e;
    }
  }
}
const rawApi=await sheets();
const api={
  spreadsheets:{
    get:(...a)=>paced(()=>rawApi.spreadsheets.get(...a)),
    batchUpdate:(...a)=>paced(()=>rawApi.spreadsheets.batchUpdate(...a)),
    values:{
      get:(...a)=>paced(()=>rawApi.spreadsheets.values.get(...a)),
      update:(...a)=>paced(()=>rawApi.spreadsheets.values.update(...a)),
      append:(...a)=>paced(()=>rawApi.spreadsheets.values.append(...a))
    }
  }
};
